import * as T from 'three/tsl';
export function pathEnvironmentNode({load,environmentScene,random,ray,brdf,mis,visibility},u){
 const environmentLoad=T.Fn(([index])=>{const count=u.pathMap.y.mul(u.pathMap.z),total=count.add(count.mul(.5).ceil()),width=total.min(4096);return T.textureLoad(environmentScene,T.ivec2(index.mod(width),index.div(width).floor())).setUpdateMatrix(false);}).setLayout({name:'hbEnvironmentLoad',type:'vec4',inputs:[{name:'index',type:'float'}]});
 const environment=T.Fn(([d])=>{const result=T.vec4(u.pathEnvironment.rgb,0).toVar();T.If(u.pathMap.y.greaterThan(.5),()=>{const uv=T.vec2(d.z.atan2(d.x).sub(u.pathMap.w).mul(.159154943).add(.5).fract(),d.y.clamp(-1,1).acos().mul(.318309886)),id=uv.y.mul(u.pathMap.z).floor().mul(u.pathMap.y).add(uv.x.mul(u.pathMap.y).floor()),v=environmentLoad(u.pathMap.x.add(id.min(u.pathMap.y.mul(u.pathMap.z).sub(1))));result.assign(T.vec4(v.rgb.mul(u.pathOptions.x),v.a));});return result;}).setLayout({name:'hbEnvironment',type:'vec4',inputs:[{name:'direction',type:'vec3'}]});
 const direction=T.Fn(([seed])=>{const count=u.pathMap.y.mul(u.pathMap.z),choice=random(seed.add(21)).mul(count),index=choice.floor().toVar(),cell=environmentLoad(u.pathMap.x.add(count).add(index.mul(.5).floor())),alias=index.mod(2).lessThan(.5).select(cell.xy,cell.zw);T.If(choice.fract().greaterThanEqual(alias.x),()=>{index.assign(alias.y);});const y=index.div(u.pathMap.y).floor(),x=index.sub(y.mul(u.pathMap.y)),phi=x.add(random(seed.add(22))).div(u.pathMap.y).sub(.5).mul(Math.PI*2).add(u.pathMap.w),cosine=T.mix(y.mul(Math.PI).div(u.pathMap.z).cos(),y.add(1).mul(Math.PI).div(u.pathMap.z).cos(),random(seed.add(23))),sine=T.float(1).sub(cosine.mul(cosine)).max(0).sqrt();return T.vec4(sine.mul(phi.cos()),cosine,sine.mul(phi.sin()),environmentLoad(u.pathMap.x.add(index)).a);}).setLayout({name:'hbEnvironmentDirection',type:'vec4',inputs:[{name:'seed',type:'float'}]});
 const direct=T.Fn(([point,n,view,id,seed])=>{const result=T.vec3(0).toVar();T.If(u.pathMap.y.greaterThan(.5).and(u.pathOptions.x.greaterThan(0)),()=>{const sampled=direction(seed),d=sampled.xyz,cosine=n.dot(d).max(0),pdf=sampled.w;T.If(cosine.greaterThan(0).and(pdf.greaterThan(0)),()=>{const p=ray.field(id,point,view,0),b=brdf(n,view,d,ray.field(id,point,view,1).rgb,p.x,p.y.max(.02)),opaque=T.float(1).sub(p.z.mul(T.float(1).sub(p.x))),visible=visibility(point.add(d.mul(u.geometryLimits.y.mul(2))),d,u.geometry.y).toVar();T.If(load(u.transport.x.add(id.mul(2)).add(1)).y.lessThan(.5),()=>{visible.assign(T.vec3(1));});result.assign(environment(d).rgb.mul(b.rgb).mul(visible).mul(cosine.mul(opaque).div(pdf)).mul(mis(pdf,b.a.mul(opaque))));});});return result;}).setLayout({name:'hbEnvironmentDirect',type:'vec3',inputs:[{name:'point',type:'vec3'},{name:'normal',type:'vec3'},{name:'view',type:'vec3'},{name:'id',type:'float'},{name:'seed',type:'float'}]});
 return {environment,direct};
}
